L["Manners commands:"] = "Manners-Befehle:"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "|cffffd100/mnr|r funktioniert bei allen anstelle von |cffffd100/manners|r."
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try-Makro gelöscht – das normale Wirken gilt nach diesem Kampf; bis dahin führt ein Klick das Makro aus, das schon auf der Schaltfläche liegt."
L["try cleared -- back to the normal cast."] = "try-Makro gelöscht – zurück zum normalen Wirken."
L["try armed: |cff80ff80%s|r"] = "try-Makro scharf: |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080vorerst nicht scharf:|r %s."
L["expands to: |cffffffff%s|r"] = "ergibt: |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d Zeichen – %d mehr als die %d, die ein Makro fasst. Der Client kürzt es, und was ausgeführt wird, ist nicht das, was oben steht."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Es gilt nach diesem Kampf; bis dahin führt ein Klick das Makro aus, das schon auf der Schaltfläche liegt. |cffffd100/manners try|r ohne Text löscht es."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Die Anzeige macht es scharf, sobald diese Person ein Unit-Token hat. |cffffd100/manners try|r ohne Text löscht es."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Klickt auf die Anzeige, um es auszuführen. |cffffd100/manners try|r ohne Text löscht es."
L["Targeting forms, for /manners try:"] = "Formen der Zielauswahl für /manners try:"
L["(on yourself)"] = "(auf Euch selbst)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Platzhalter: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. Unter {name} wird ein offener Gefallen geführt, {aim} ist das, was eine Zielzeile braucht. Mit \\n beginnt eine neue Zeile."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "das Gefallen-Buch wurde nicht geladen – eine Neuinstallation von Manners sollte es zurückbringen."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "entsperrt – nach diesem Kampf lässt sich die Anzeige verschieben; bis dahin wirkt ein Klick noch, was der Kampf eingefroren hat. Danach |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "entsperrt – verschiebt die Anzeige, dann |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "entsperrt, aber das Addon ist |cffff8080aus|r, also gibt es keine Anzeige zum Verschieben – zuerst |cffffd100/manners on|r."
L["locked."] = "gesperrt."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "Ziel nach dem Stärken wiederherstellen: |cff00ff00an|r – gilt nach diesem Kampf; bis dahin führt ein Klick das Makro aus, das schon auf der Schaltfläche liegt."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "Ziel nach dem Stärken wiederherstellen: |cffff0000aus|r – gilt nach diesem Kampf; bis dahin führt ein Klick das Makro aus, das schon auf der Schaltfläche liegt."
L["hand your target back after buffing: |cff00ff00on|r"] = "Ziel nach dem Stärken wiederherstellen: |cff00ff00an|r"
